import {el,button,field,busy,notify,badge,dateText} from './utils.js';
import {api} from './service.js';
import {accountName} from './model.js';
export function manualReplyPanel(thread,data,refresh){
 const root=el('section',{class:'review-tile','aria-label':'Reviewed manual reply'},el('h3',{text:'Reply in this conversation'}));const account=data.accounts.find(a=>a.id===thread.accountId);const channel=thread.channel;const allowed=['linkedin','instagram'].includes(channel)&&account?.capabilities?.socialMessage;
 if(!allowed){root.append(el('p',{class:'field-help',text:channel==='email'?'Use Mailbox drafts for email. Zoho sending stays manual in Zoho.':'Messaging is unavailable for this account. X and TikTok messaging are not supported.'}));return root;}
 const history=el('div');const composer=el('textarea',{class:'field-control','data-retain-input':'true',name:'manualReply',rows:5,maxlength:channel==='instagram'?1000:3000});const error=el('p',{class:'banner error',role:'alert',hidden:''});let requestKey=globalThis.crypto.randomUUID();
 const show=reply=>{const card=el('article',{class:'review-entry'},badge(reply.state),el('p',{text:reply.review.text}),el('small',{text:`${accountName(account)} · ${reply.review.channel} · ${reply.review.peerUrl}`}),el('small',{text:`Native conversation: ${reply.review.nativeThreadId}`}),el('small',{text:`Prepared ${dateText(reply.dueAt)}`}));if(reply.reason)card.append(el('p',{class:'field-help',text:reply.reason}));for(const attempt of reply.attempts||[])card.append(el('p',{class:'field-help',text:`Attempt ${attempt.attempt_no}: ${attempt.outcome}${attempt.receipt?.providerMessageId?' · Native receipt '+attempt.receipt.providerMessageId:''}`}));
  if(reply.state==='awaiting_approval'&&data.roles?.some(r=>['admin','approver'].includes(r))){const decide=decision=>{const b=button(decision==='approved'?'Approve this exact reply':'Reject this exact reply',()=>busy(b,async()=>{await api('approval-decide',{approvalId:reply.authorizationId,operationHash:reply.operationHash,decision,reason:'Reviewed exact conversation and response in Inbox'});await load();await refresh();notify(decision==='approved'?'Reply approved for the cloud worker.':'Reply rejected.');}),decision==='approved'?'primary':'danger');return b;};card.append(el('p',{class:'field-help',text:'Review the account, native conversation, recipient and exact response before deciding.'}),decide('rejected'),decide('approved'));}return card;};
 async function load(){try{const result=await api('inbox-replies',{threadId:thread.id});history.replaceChildren(...result.replies.map(show));}catch(e){history.replaceChildren(el('p',{class:'banner error',role:'alert',text:`Reply records could not refresh: ${e.message}`}));}}
 if(data.roles?.some(r=>['operator','approver','admin'].includes(r))){const prepare=button('Review response',()=>busy(prepare,async()=>{error.hidden=true;try{if(!composer.value.trim()){composer.focus();throw new Error('Enter your response first.');}const result=await api('inbox-reply-prepare',{threadId:thread.id,text:composer.value,idempotencyKey:requestKey});history.replaceChildren(show(result.reply));requestKey=globalThis.crypto.randomUUID();composer.value='';await refresh();notify('Response prepared for exact approval. Nothing has been sent.');}catch(e){error.hidden=false;error.textContent=e.message;}}),'primary');root.append(field('Your response',composer),el('p',{class:'field-help',text:'Preparing saves an exact approval request. The worker sends only after an approver reviews this recipient and native conversation.'}),error,prepare);}
 root.append(history);void load();return root;
}
